import sys

def main():
    data = sys.stdin.read().split()
    s, p = data[0], data[1]
    n, m = len(s), len(p)
    if m > n:
        print('NO')
        return
    need = [0] * 26
    for ch in p:
        need[ord(ch) - 97] += 1
    have = [0] * 26
    ok = sum(1 for k in range(26) if need[k] == 0)  # letters whose counts match
    def add(c, d):
        nonlocal ok
        if have[c] == need[c]:
            ok -= 1
        have[c] += d
        if have[c] == need[c]:
            ok += 1
    for i in range(n):
        add(ord(s[i]) - 97, 1)
        if i >= m:
            add(ord(s[i - m]) - 97, -1)
        if i >= m - 1 and ok == 26:
            print('YES')
            return
    print('NO')

